const templates=Object.entries(EN).filter(([key])=>/\{\d+\}/.test(key)).map(([key,value])=>{
  const escaped=key.replace(/[.*+?^$()|[\]\\]/g,'\\$&');
  return{pattern:new RegExp('^'+escaped.replace(/\{\d+\}/g,'(.*?)')+'$'),value};
});
export function t(text:string,values:Record<string,string|number>={}):string{
  let result=text;
  if(getLang()==='en'){
    const key=text.trim();
    if(EN[key]!==undefined)result=text.replace(key,EN[key]);
    else{
      for(const rule of templates){const match=rule.pattern.exec(key);if(match){result=rule.value.replace(/\{(\d+)\}/g,(_,index)=>match[Number(index)+1]??'');break}}
      if(result===text&&text.includes('\n'))result=text.split('\n').map(line=>t(line)).join('\n');
      if(result===text)for(const [prefix,value] of Object.entries(EN)){if(prefix.endsWith('：')&&text.startsWith(prefix)){result=value+t(text.slice(prefix.length));break}}
    }
  }
  return result.replace(/\{(\d+)\}/g,(token,key)=>Object.prototype.hasOwnProperty.call(values,key)?String(values[key]):token);
}
export function getLocale():string{return getLang()==='en'?'en-US':'zh-CN'}
export function monthName(month:string|number):string{return getLang()==='zh'?`${Number(month)}月`:new Date(Date.UTC(2000,Number(month)-1)).toLocaleString(getLocale(),{month:'long',timeZone:'UTC'})}
